CREATE OR ALTER PROCEDURE [dbo].[uspQcInspection_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @GoodsReceiptId UNIQUEIDENTIFIER = NULL
	, @InspectorEmployeeId UNIQUEIDENTIFIER = NULL
	, @InspectionNumber NVARCHAR(MAX) = NULL
	, @InspectionDate DATETIME = NULL
	, @Result NVARCHAR(MAX) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[GoodsReceiptId]
			, j1.[ReceiptNo] AS [GoodsReceiptName]
			, t.[InspectionDate]
			, t.[Result]
			, t.[Remark]
			, t.[InspectionNumber]
			, t.[InspectorEmployeeId]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[QCInspection] AS t
		LEFT JOIN [dbo].[GoodsReceipt] AS j1 ON j1.[Id] = t.[GoodsReceiptId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[InspectionNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (@GoodsReceiptId IS NULL OR t.[GoodsReceiptId] = @GoodsReceiptId)
			AND (@InspectorEmployeeId IS NULL OR t.[InspectorEmployeeId] = @InspectorEmployeeId)
			AND (ISNULL(@InspectionNumber, '') = '' OR t.[InspectionNumber] LIKE CONCAT('%', @InspectionNumber, '%'))
			AND (@InspectionDate IS NULL OR t.[InspectionDate] = @InspectionDate)
			AND (ISNULL(@Result, '') = '' OR t.[Result] LIKE CONCAT('%', @Result, '%'))
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'goodsReceiptId' THEN r.[GoodsReceiptId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'goodsReceiptId' THEN r.[GoodsReceiptId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'goodsReceiptName' THEN r.[GoodsReceiptName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'goodsReceiptName' THEN r.[GoodsReceiptName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'inspectionDate' THEN r.[InspectionDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'inspectionDate' THEN r.[InspectionDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'result' THEN r.[Result] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'result' THEN r.[Result] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'remark' THEN r.[Remark] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'remark' THEN r.[Remark] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'inspectionNumber' THEN r.[InspectionNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'inspectionNumber' THEN r.[InspectionNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'inspectorEmployeeId' THEN r.[InspectorEmployeeId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'inspectorEmployeeId' THEN r.[InspectorEmployeeId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
